#Requires -Version 5.1
# fix-partes-firma-permiso-rls.ps1
#
# CAUSA EXACTA DEL BUG (dos problemas combinados en RLS, no en el canvas de firma):
#
# 1. La politica "partes_update" (migracion 024) solo permitia escribir a
#    admin o a created_by = auth.uid(). Ignoraba por completo rol_permisos /
#    canDo("partes","editar"). Un Jefe de obra con permiso "editar" explicito
#    pero que no es el creador del parte quedaba bloqueado por RLS.
# 2. Mas profundo: esa politica NO definia WITH CHECK explicito. En Postgres,
#    si una politica UPDATE omite WITH CHECK, reutiliza la misma expresion de
#    USING para validar tambien la FILA RESULTANTE. Como USING exigia
#    estado IN (borrador,pendiente,rechazado), esa misma condicion se
#    aplicaba al NUEVO estado -- y firmar pone estado='firmado', que siempre
#    incumplia esa condicion. Resultado: NINGUN no-admin ha podido firmar
#    nunca un parte por esta via, ni siquiera el propio creador.
# 3. El frontend (handleFirmar/handleSave) hacia .update() SIN comprobar
#    {error} ni si se actualizo alguna fila. Un update bloqueado por RLS no
#    lanza excepcion, solo afecta 0 filas -- de ahi el fallo 100% silencioso.
#
# IMPLEMENTACION:
#
# 1. src/app/partes/[id]/page.tsx (MODIFICADO)
#    - Nuevo puedeFirmar = isAdmin || canDo("partes","editar") || creador
#      del parte. No depende de email, nombre de rol, ni otros modulos.
#      Coincide exactamente con la politica RLS (ver abajo).
#    - Boton "Firmar" deshabilitado + tooltip cuando !puedeFirmar.
#    - handleSave y handleFirmar ahora comprueban {error} Y que la fila
#      afectada exista (.select("id")) en CADA escritura (partes_diarios,
#      parte_lineas delete, parte_lineas insert). Si falla: mensaje de error
#      visible en pantalla (accionError) + logAuditErrorClient (sistema de
#      auditoria EXISTENTE, sin catch vacio, sin bloquear la interfaz).
#    - Al firmar con exito: confirmacion visible (alert), PDF/email se
#      ejecutan igual que antes; si el email falla, el parte queda firmado
#      igualmente (no bloqueante) y se avisa que se puede reenviar.
#    - fetchData() tras firmar para reflejar el nuevo estado sin recargar.
#
# 2. supabase/migrations/044_partes_firma_permiso_rls.sql (NUEVO)
#    - Funcion user_has_permiso(pantalla, accion): replica exactamente
#      usePermissions().canDo() del frontend (admin -> true; rol.is_admin
#      -> true; si no, columna de rol_permisos). Reutilizable en RLS.
#    - Politica "partes_update" reescrita con USING + WITH CHECK separados:
#        USING:      solo se pueden tocar partes en borrador/pendiente/
#                    rechazado, y solo si eres admin, el creador, o tienes
#                    permiso "editar" en Partes.
#        WITH CHECK: solo valida quien puede dejar la fila asi (admin,
#                    creador o permiso editar) -- SIN volver a exigir el
#                    estado antiguo sobre la fila nueva, permitiendo asi la
#                    transicion a 'firmado'.
#      No se amplia nada para roles de solo lectura (editar=false y no
#      creador siguen bloqueados).
#
# AUDIT LOG: partes_diarios ya tenia trigger de auditoria en BD para
# operaciones EXITOSAS (audit_partes, migracion 001) -- sin cambios ahi.
# Lo que faltaba y se anade ahora es el registro de los INTENTOS FALLIDOS
# desde el cliente (logAuditErrorClient, sistema ya existente, reutilizado
# tal cual, mismo patron que el ErrorBoundary del Planificador).
#
# EJECUCION: requiere ejecutar la migracion SQL en Supabase (SQL Editor)
# ADEMAS del push a git (Vercel no aplica migraciones automaticamente).

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR: no se encuentra $RepoPath" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> fix: Jefe de obra (y cualquier usuario con partes->editar) puede firmar partes" -ForegroundColor Cyan

Write-Host "  -> src\app\partes\[id]\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\partes\[id]\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), $bytes)
Write-Host "  OK: 33 KB" -ForegroundColor Green

Write-Host "  -> supabase\migrations\044_partes_firma_permiso_rls.sql" -ForegroundColor Gray
$dir2 = Split-Path -Parent (Join-Path $RepoPath "supabase\migrations\044_partes_firma_permiso_rls.sql")
if (-not (Test-Path $dir2)) { New-Item -ItemType Directory -Path $dir2 -Force | Out-Null }
$bytes2 = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "supabase\migrations\044_partes_firma_permiso_rls.sql"), $bytes2)
Write-Host "  OK: 5 KB" -ForegroundColor Green

$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), [System.Text.Encoding]::UTF8)
$sql  = [System.IO.File]::ReadAllText((Join-Path $RepoPath "supabase\migrations\044_partes_firma_permiso_rls.sql"), [System.Text.Encoding]::UTF8)
if ($page.Contains('const puedeFirmar = puedeEditar || parte?.created_by === user?.id'))  { Write-Host "  OK: permiso correcto isAdmin||canDo(partes,editar)||creador" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('logAuditErrorClient'))                                                { Write-Host "  OK: errores registrados en audit_log" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('!updated || updated.length === 0'))                                   { Write-Host "  OK: deteccion de bloqueo silencioso por RLS" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($sql.Contains('CREATE OR REPLACE FUNCTION user_has_permiso'))                         { Write-Host "  OK: funcion user_has_permiso creada" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($sql.Contains('WITH CHECK ('))                                                        { Write-Host "  OK: WITH CHECK explicito (permite transicion a firmado)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  IMPORTANTE: ademas de git push, ejecuta el contenido de" -ForegroundColor Yellow
Write-Host "  supabase\migrations\044_partes_firma_permiso_rls.sql en el SQL Editor de Supabase." -ForegroundColor Yellow
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: RLS partes_update alineada con permisos (Jefe de obra puede firmar)"'
Write-Host "  git push"
Write-Host ""
Write-Host "  Despues del deploy: Vercel -> Deployments -> ... -> Promote to Production" -ForegroundColor Yellow
